float FCluster::GetCurveBoundsRadius() const
{
	if (!IsCurve() || !Verts.Format.bHasCurveRadius)
	{
		return 0.0f;
	}
	float MaxRadius = 0.0f;
	for (uint32 VertexIndex = 0; VertexIndex < Verts.Num(); ++VertexIndex)
	{
		MaxRadius = FMath::Max(MaxRadius, Verts.GetCurveRadius(VertexIndex));
	}
	// The stored radius is an eight-bit integer times a ten-bit float scale.
	// Half conversion rounds before the low mantissa bits are discarded; cover
	// the reconstructed maximum as well as the original authored radius.
	FFloat16 EncodedScale;
	EncodedScale.Encoded = uint16(ToFloat10(MaxRadius / 255.0f) << 5);
	return FMath::Max(MaxRadius, EncodedScale.GetFloat() * 255.0f);
}

